<?php require 'bootstrap.php';require 'layout.php';$q=trim($_GET['q']??'');$cat=(int)($_GET['cat']??0);$cats=db()->query('SELECT * FROM categories ORDER BY name')->fetchAll();$st=db()->prepare('SELECT p.*,c.name category FROM products p JOIN categories c ON c.id=p.category_id WHERE p.is_active=1 AND (:cat=0 OR p.category_id=:cat2) AND (p.name LIKE :q OR p.description LIKE :q2) ORDER BY p.id DESC');$st->execute(['cat'=>$cat,'cat2'=>$cat,'q'=>"%$q%",'q2'=>"%$q%"]);$items=$st->fetchAll();head_html('Computer Parts');?>
<section class="hero"><span class="accent">BUILD BETTER. PLAY HARDER.</span><h1>Power your next <span class="accent">PC build.</span></h1><p>Discover processors, graphics cards, storage and essentials for your dream setup.</p><a class="btn" href="#catalog">Explore components →</a></section>
<h2 id="catalog">Shop components</h2><form class="filters" method="get"><input name="q" value="<?=e($q)?>" placeholder="Search computer parts..."><select name="cat"><option value="0">All categories</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=$cat==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select><button class="btn">Search</button></form><div class="grid"><?php foreach($items as $i):?><article class="product"><img src="<?=e($i['image_url'] ?: 'https://placehold.co/600x400/172336/ffffff?text=PC+Part')?>" alt="<?=e($i['name'])?>"><p class="muted"><?=e($i['category'])?></p><h3><?=e($i['name'])?></h3><p class="price">₱<?=number_format($i['price'],2)?></p><p class="muted"><?= (int)$i['stock']?> in stock</p><form action="cart.php" method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="product_id" value="<?=$i['id']?>"><input type="hidden" name="action" value="add"><button class="btn" <?=$i['stock']<1?'disabled':''?>>Add to cart</button></form></article><?php endforeach;?></div><?php if(!$items):?><p>No products found.</p><?php endif;foot_html();